import test from 'node:test';import assert from 'node:assert/strict';
import {mapRegions,regionSites,regionForPlace,adjacentRegion} from './region-map.js';import {locations} from './days.js';
test('every destination belongs to a connected region with a valid pin',()=>{const visited=new Set(['north']),queue=['north'];while(queue.length){for(const target of Object.values(mapRegions[queue.shift()].links)){assert.ok(mapRegions[target]);if(!visited.has(target)){visited.add(target);queue.push(target);}}}assert.equal(visited.size,8);for(const id of Object.keys(locations)){const [region,x,y]=regionSites[id];assert.ok(visited.has(region));assert.ok(x>0&&x<100&&y>0&&y<100);}assert.equal(regionForPlace('campus'),'north');assert.equal(adjacentRegion('north','west'),null);assert.equal(adjacentRegion('north','south'),'athletics');});
